import java.io.*;
import java.util.*;

public class Main {
    static class Node { int val; Node left, right; Node(int v) { val = v; } }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        String s = line.trim();
        if (s.startsWith("[")) s = s.substring(1);
        if (s.endsWith("]")) s = s.substring(0, s.length() - 1);
        s = s.trim();
        if (s.isEmpty()) { System.out.println(0); return; }
        String[] parts = s.split(",");
        int n = parts.length;
        Integer[] v = new Integer[n];
        for (int i = 0; i < n; i++) { String t = parts[i].trim(); v[i] = t.equalsIgnoreCase("null") ? null : Integer.valueOf(t); }
        if (v[0] == null) { System.out.println(0); return; }
        Node root = new Node(v[0]);
        ArrayDeque<Node> q = new ArrayDeque<>();
        q.add(root);
        int idx = 1;
        while (!q.isEmpty() && idx < n) {
            Node cur = q.poll();
            if (idx < n) { if (v[idx] != null) { cur.left = new Node(v[idx]); q.add(cur.left); } idx++; }
            if (idx < n) { if (v[idx] != null) { cur.right = new Node(v[idx]); q.add(cur.right); } idx++; }
        }
        ArrayDeque<Node> lv = new ArrayDeque<>();
        lv.add(root);
        int depth = 0;
        while (!lv.isEmpty()) {
            int sz = lv.size();
            depth++;
            for (int i = 0; i < sz; i++) { Node cur = lv.poll(); if (cur.left != null) lv.add(cur.left); if (cur.right != null) lv.add(cur.right); }
        }
        System.out.println(depth);
    }
}

