public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        String[] seg = line.trim().split(";");
        int n = Integer.parseInt(seg[0].trim());
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<Integer>());
        List<Integer> nums = new ArrayList<>();
        Matcher m = Pattern.compile("-?[0-9]+").matcher(seg[1]);
        while (m.find()) nums.add(Integer.parseInt(m.group()));
        for (int i = 0; i + 1 < nums.size(); i += 2) {
            int u = nums.get(i), v = nums.get(i + 1);
            adj.get(u).add(v);
            adj.get(v).add(u);
        }
        int src = Integer.parseInt(seg[2].trim()), dst = Integer.parseInt(seg[3].trim());
        boolean[] vis = new boolean[n];
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(src);
        vis[src] = true;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int w : adj.get(u)) if (!vis[w]) { vis[w] = true; q.add(w); }
        }
        System.out.println(vis[dst] ? "true" : "false");
    }
}

