            if (idx < n) { if (v[idx] != null) { cur.right = new Node(v[idx]); q.add(cur.right); } idx++; }
        }
        ArrayDeque<Node> st = new ArrayDeque<>();
        Node cur = root;
        long prev = Long.MIN_VALUE;
