            cur = cur.right;
        }
        System.out.println(ok ? "true" : "false");
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static int[] parse(String s) {
        String t = s.trim();
        if (t.startsWith("[")) t = t.substring(1);
        if (t.endsWith("]")) t = t.substring(0, t.length() - 1);
        t = t.trim();
        if (t.isEmpty()) return new int[0];
        String[] p = t.split(",");
        int[] a = new int[p.length];
        for (int i = 0; i < p.length; i++) a[i] = Integer.parseInt(p[i].trim());
        return a;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        String[] seg = line.trim().split(";");
        int[] a = parse(seg[0]), b = parse(seg[1]);
        List<Integer> out = new ArrayList<>();
        int i = 0, j = 0, carry = 0;
        while (i < a.length || j < b.length || carry > 0) {
            int sum = carry;
            if (i < a.length) sum += a[i++];
            if (j < b.length) sum += b[j++];
            out.add(sum % 10);
            carry = sum / 10;
        }
        StringBuilder sb = new StringBuilder("[");
        for (int k = 0; k < out.size(); k++) { if (k > 0) sb.append(','); sb.append(out.get(k)); }
        sb.append(']');
        System.out.println(sb);
    }
}

