public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        List<int[]> rows = new ArrayList<>();
        Matcher m = Pattern.compile("\\[([^\\[\\]]*)\\]").matcher(line);
        while (m.find()) {
            String c = m.group(1).trim();
            if (c.isEmpty()) continue;
            String[] p = c.split(",");
            int[] row = new int[p.length];
            for (int i = 0; i < p.length; i++) row[i] = Integer.parseInt(p[i].trim());
            rows.add(row);
        }
        if (rows.isEmpty()) { System.out.println(0); return; }
        int rn = rows.size(), cn = rows.get(0).length;
        int[][] g = new int[rn][];
        for (int i = 0; i < rn; i++) g[i] = rows.get(i);
        int[] dr = {-1, 1, 0, 0}, dc = {0, 0, -1, 1};
        ArrayDeque<Integer> q = new ArrayDeque<>();
        int best = 0;
        for (int r = 0; r < rn; r++) {
            for (int c2 = 0; c2 < cn; c2++) {
                if (g[r][c2] != 1) continue;
                g[r][c2] = 0;
                q.add(r * cn + c2);
                int area = 0;
                while (!q.isEmpty()) {
                    int cur = q.poll();
                    area++;
                    int cr = cur / cn, cc = cur % cn;
                    for (int d = 0; d < 4; d++) {
                        int nr = cr + dr[d], nc = cc + dc[d];
                        if (nr >= 0 && nr < rn && nc >= 0 && nc < cn && g[nr][nc] == 1) { g[nr][nc] = 0; q.add(nr * cn + nc); }
                    }
                }
                if (area > best) best = area;
            }
        }
        System.out.println(best);
    }
}

