public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        List<int[]> rows = new ArrayList<>();
        Matcher m = Pattern.compile("\\[([^\\[\\]]*)\\]").matcher(line);
        while (m.find()) {
            String c = m.group(1).trim();
            if (c.isEmpty()) continue;
            String[] p = c.split(",");
            int[] row = new int[p.length];
            for (int i = 0; i < p.length; i++) row[i] = Integer.parseInt(p[i].trim());
            rows.add(row);
        }
        if (rows.isEmpty()) { System.out.println(0); return; }
        int rn = rows.size(), cn = rows.get(0).length;
        int[][] g = new int[rn][];
        for (int i = 0; i < rn; i++) g[i] = rows.get(i);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        int fresh = 0;
        for (int r = 0; r < rn; r++) for (int c = 0; c < cn; c++) {
            if (g[r][c] == 2) q.add(r * cn + c);
            else if (g[r][c] == 1) fresh++;
        }
        if (fresh == 0) { System.out.println(0); return; }
        int[] dr = {-1, 1, 0, 0}, dc = {0, 0, -1, 1};
        int minutes = 0;
        while (!q.isEmpty() && fresh > 0) {
            int sz = q.size();
            for (int k = 0; k < sz; k++) {
                int cur = q.poll();
                int cr = cur / cn, cc = cur % cn;
                for (int d = 0; d < 4; d++) {
                    int nr = cr + dr[d], nc = cc + dc[d];
                    if (nr >= 0 && nr < rn && nc >= 0 && nc < cn && g[nr][nc] == 1) { g[nr][nc] = 2; fresh--; q.add(nr * cn + nc); }
                }
            }
            minutes++;
        }
        System.out.println(fresh == 0 ? minutes : -1);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        String[] seg = line.trim().split(";");
        String begin = seg[0].trim(), end = seg[1].trim();
        Set<String> dict = new HashSet<>();
        if (seg.length > 2) for (String w : seg[2].trim().split(",")) { String t = w.trim(); if (!t.isEmpty()) dict.add(t); }
        if (!dict.contains(end)) { System.out.println(0); return; }
        if (begin.equals(end)) { System.out.println(1); return; }
        ArrayDeque<String> q = new ArrayDeque<>();
        Set<String> vis = new HashSet<>();
        q.add(begin);
        vis.add(begin);
        int steps = 1;
        while (!q.isEmpty()) {
            int sz = q.size();
            for (int k = 0; k < sz; k++) {
                char[] arr = q.poll().toCharArray();
                for (int i = 0; i < arr.length; i++) {
                    char old = arr[i];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == old) continue;
                        arr[i] = c;
                        String nw = new String(arr);
                        if (dict.contains(nw) && !vis.contains(nw)) {
                            if (nw.equals(end)) { System.out.println(steps + 1); return; }
                            vis.add(nw);
                            q.add(nw);
                        }
                    }
                    arr[i] = old;
                }
            }
            steps++;
        }
        System.out.println(0);
    }
}
